use "./sim.ts" { createSim }

page Home "/" {
  state count = 5
  state frames = 0
  state paused = false
  ref box
  ref sim

  mount {
    sim = createSim(box, (n, f) => { count = n; frames = f })
    cleanup { sim.destroy() }
  }

  fn toggle() {
    if paused {
      sim.resume()
    } else {
      sim.pause()
    }
    paused = !paused
  }

  fn restart() {
    sim.reset()
    paused = false
  }

  column gap=3 pad=4 align=center {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> sim.add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" danger -> restart()
    }
    row gap=4 {
      text `Pelotas: ${count}`
      text `Cuadros: ${frames}`
    }
  }
}

