const W = 400
const H = 300
const R = 10
const G = 0.2

type Ball = { x: number; y: number; vx: number; vy: number }

function makeBall(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
  }
}

export function createSim(canvas: HTMLCanvasElement, onChange: (n: number, f: number) => void) {
  const ctx = canvas.getContext("2d") as CanvasRenderingContext2D
  let balls: Ball[] = []
  let frames = 0
  let raf = 0
  let running = false

  function init() {
    balls = []
    for (let i = 0; i < 5; i++) balls.push(makeBall())
    frames = 0
  }

  function step() {
    for (const b of balls) {
      b.vy += G
      b.x += b.vx
      b.y += b.vy
      if (b.x < R) { b.x = R; b.vx = Math.abs(b.vx) }
      if (b.x > W - R) { b.x = W - R; b.vx = -Math.abs(b.vx) }
      if (b.y < R) { b.y = R; b.vy = Math.abs(b.vy) }
      if (b.y > H - R) { b.y = H - R; b.vy = -Math.abs(b.vy) }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i]
        const b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let d = Math.sqrt(dx * dx + dy * dy)
        if (d >= 2 * R) continue
        if (d === 0) { dx = 1; dy = 0; d = 1 }
        const nx = dx / d
        const ny = dy / d
        const overlap = 2 * R - d
        a.x -= (nx * overlap) / 2
        a.y -= (ny * overlap) / 2
        b.x += (nx * overlap) / 2
        b.y += (ny * overlap) / 2
        const rel = (a.vx - b.vx) * nx + (a.vy - b.vy) * ny
        if (rel > 0) {
          a.vx -= rel * nx
          a.vy -= rel * ny
          b.vx += rel * nx
          b.vy += rel * ny
        }
        for (const p of [a, b]) {
          p.x = Math.min(W - R, Math.max(R, p.x))
          p.y = Math.min(H - R, Math.max(R, p.y))
        }
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H)
    ctx.fillStyle = "#3b82f6"
    for (const b of balls) {
      ctx.beginPath()
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  function loop() {
    if (!running) return
    step()
    draw()
    frames++
    onChange(balls.length, frames)
    raf = requestAnimationFrame(loop)
  }

  function resume() {
    if (running) return
    running = true
    raf = requestAnimationFrame(loop)
  }

  function pause() {
    running = false
    cancelAnimationFrame(raf)
  }

  init()
  draw()
  onChange(balls.length, frames)
  resume()

  return {
    add() {
      balls.push(makeBall())
      draw()
      onChange(balls.length, frames)
    },
    reset() {
      init()
      draw()
      onChange(balls.length, frames)
      resume()
    },
    pause,
    resume,
    destroy() {
      pause()
    },
  }
}

