const W = 400
const H = 300
const R = 10
const G = 0.2

fn makeBall() {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6
  }
}

fn makeBalls(n) {
  let out = []
  for (let i = 0; i < n; i++) {
    out.push(makeBall())
  }
  return out
}

fn stepBalls(balls) {
  for (let i = 0; i < balls.length; i++) {
    let b = balls[i]
    b.vy += G
    b.x += b.vx
    b.y += b.vy
    if (b.x < R) { b.x = R; b.vx = Math.abs(b.vx) }
    if (b.x > W - R) { b.x = W - R; b.vx = -Math.abs(b.vx) }
    if (b.y < R) { b.y = R; b.vy = Math.abs(b.vy) }
    if (b.y > H - R) { b.y = H - R; b.vy = -Math.abs(b.vy) }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      let a = balls[i]
      let b = balls[j]
      let dx = b.x - a.x
      let dy = b.y - a.y
      let dist = Math.sqrt(dx * dx + dy * dy)
      if (dist < 2 * R) {
        if (dist == 0) {
          dx = 1
          dy = 0
          dist = 1
        }
        let nx = dx / dist
        let ny = dy / dist
        let overlap = 2 * R - dist
        a.x -= nx * overlap / 2
        a.y -= ny * overlap / 2
        b.x += nx * overlap / 2
        b.y += ny * overlap / 2
        a.x = Math.min(Math.max(a.x, R), W - R)
        a.y = Math.min(Math.max(a.y, R), H - R)
        b.x = Math.min(Math.max(b.x, R), W - R)
        b.y = Math.min(Math.max(b.y, R), H - R)
        let rel = (a.vx - b.vx) * nx + (a.vy - b.vy) * ny
        if (rel > 0) {
          a.vx -= rel * nx
          a.vy -= rel * ny
          b.vx += rel * nx
          b.vy += rel * ny
        }
      }
    }
  }
}

fn drawBalls(ctx, balls) {
  ctx.clearRect(0, 0, W, H)
  ctx.fillStyle = "#3b82f6"
  for (let i = 0; i < balls.length; i++) {
    ctx.beginPath()
    ctx.arc(balls[i].x, balls[i].y, R, 0, Math.PI * 2)
    ctx.fill()
  }
}

page Sim "/" {
  state count = 5
  state frames = 0
  state paused = false
  ref box
  ref balls
  ref raf
  ref ctx

  fn loop() {
    if !paused {
      stepBalls(balls)
      frames++
    }
    drawBalls(ctx, balls)
    raf = requestAnimationFrame(loop)
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
  }

  fn restart() {
    balls = makeBalls(5)
    count = 5
    frames = 0
  }

  mount {
    ctx = box.getContext("2d")
    balls = makeBalls(5)
    loop()
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> paused = !paused
      button "Reiniciar" danger -> restart()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

// ───────── Datos ─────────
const TRAVELERS = [
  { id: 1, name: "Ana Rojas", country: "Perú", city: "Lima", arrival: "2026-03-12", budget: 1200 },
  { id: 2, name: "Bruno Díaz", country: "México", city: "Oaxaca", arrival: "2026-01-05", budget: 850 },
  { id: 3, name: "Carla Gómez", country: "Perú", city: "Cusco", arrival: "2026-02-20", budget: 2300 },
  { id: 4, name: "Diego Silva", country: "Chile", city: "Valparaíso", arrival: "2026-04-02", budget: 640 },
  { id: 5, name: "Elena Ruiz", country: "México", city: "Mérida", arrival: "2026-03-01", budget: 1500 },
  { id: 6, name: "Facundo Paz", country: "Argentina", city: "Salta", arrival: "2026-02-11", budget: 990 },
  { id: 7, name: "Gabriela Luna", country: "Chile", city: "Santiago", arrival: "2026-01-28", budget: 1750 },
  { id: 8, name: "Hugo Vera", country: "Argentina", city: "Mendoza", arrival: "2026-03-30", budget: 1100 }
]

const COUNTRIES = ["Todos", "Argentina", "Chile", "México", "Perú"]

// ───────── Utilidades de formato ─────────
fn formatDate(iso) {
  const parts = iso.split("-")
  return `${parts[2]}/${parts[1]}/${parts[0]}`
}

fn formatBudget(n) {
  return "US$ " + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ".")
}

fn initials(name) {
  return name.split(" ").filter(p => p.length > 0).slice(0, 2).map(p => p[0].toUpperCase()).join("")
}

fn avatarColor(name) {
  let h = 0
  for (let i = 0; i < name.length; i++) {
    h = (h * 31 + name.charCodeAt(i)) % 360
  }
  return `hsl(${h}, 55%, 45%)`
}

fn avatarStyle(name) {
  return `background:${avatarColor(name)};color:#fff;width:44px;height:44px;border-radius:50%;flex-shrink:0`
}

fn place(t) {
  return `${t.city}, ${t.country}`
}

// ───────── Componentes ─────────
component Avatar(name: String) {
  row style=(avatarStyle(name)) align=center justify=center {
    text initials(name) bold
  }
}

component TravelerRow(t: Any) {
  row gap=3 align=center {
    Avatar name=t.name
    column gap=1 {
      link t.name to=`/viajero/${t.id}`
      text place(t) muted
      text `Llega el ${formatDate(t.arrival)}` small
      text formatBudget(t.budget) small
    }
  }
}

// ───────── Páginas ─────────
page Home "/" {
  state country = "Todos"
  computed shown = TRAVELERS
    .filter(t => country == "Todos" || t.country == country)
    .slice()
    .sort((a, b) => a.arrival < b.arrival ? -1 : a.arrival > b.arrival ? 1 : 0)

  column gap=4 pad=4 {
    title "Viajeros" tag=h1
    text `${shown.length} viajeros`
    select country options=COUNTRIES label="País"
    column gap=3 {
      for t in shown key t.id {
        TravelerRow t=t
      }
    }
  }
}

page Traveler "/viajero/:id" {
  computed t = TRAVELERS.find(x => String(x.id) == params.id)

  column gap=3 pad=4 {
    if t {
      title t.name tag=h1
      text place(t)
      text `Llega el ${formatDate(t.arrival)}`
      text `Presupuesto: ${formatBudget(t.budget)}`
    } else {
      title "Viajero no encontrado"
    }
    link "Volver" to="/"
  }
}

